package io.github.diodeme.ji.session.sqlite;

import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.session.codec.json.JacksonSessionCodec;
import io.github.diodeme.ji.session.tree.SessionDocument;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.UnaryOperator;

/** Transactional SQLite canonical Session repository using WAL and revision CAS. */
public final class SqliteSessionRepository implements SessionRepository {
    private final Connection connection;
    private final JacksonSessionCodec codec = new JacksonSessionCodec();
    private boolean closed;

    public SqliteSessionRepository(Path database) {
        try {
            connection = DriverManager.getConnection("jdbc:sqlite:" + database.toAbsolutePath().normalize());
            try (Statement statement = connection.createStatement()) {
                statement.execute("PRAGMA journal_mode=WAL");
                statement.execute("PRAGMA synchronous=FULL");
                statement.execute("PRAGMA busy_timeout=5000");
                statement.execute("""
                        CREATE TABLE IF NOT EXISTS ji_sessions (
                          session_id TEXT PRIMARY KEY,
                          revision INTEGER NOT NULL CHECK (revision >= 0),
                          created_at TEXT NOT NULL,
                          document BLOB NOT NULL
                        )
                        """);
            }
        } catch (SQLException exception) {
            throw storage("cannot open SQLite Session repository", exception);
        }
    }

    @Override
    public synchronized SessionDocument create(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        requireOpen();
        SessionDocument created = SessionDocument.empty(sessionId, model, workingDirectory, createdAt);
        try (PreparedStatement statement = connection.prepareStatement(
                "INSERT INTO ji_sessions(session_id, revision, created_at, document) VALUES (?, ?, ?, ?)")) {
            statement.setString(1, sessionId);
            statement.setLong(2, created.revision());
            statement.setString(3, createdAt.toString());
            statement.setBytes(4, codec.encode(created));
            statement.executeUpdate();
            return created;
        } catch (SQLException exception) {
            if (isConstraint(exception)) throw new IllegalStateException("session already exists: " + sessionId, exception);
            throw storage("cannot create SQLite Session", exception);
        }
    }

    @Override
    public synchronized Optional<SessionDocument> load(String sessionId) {
        requireOpen();
        try (PreparedStatement statement = connection.prepareStatement(
                "SELECT revision, document FROM ji_sessions WHERE session_id = ?")) {
            statement.setString(1, sessionId);
            try (ResultSet result = statement.executeQuery()) {
                if (!result.next()) return Optional.empty();
                long revision = result.getLong(1);
                SessionDocument document = codec.decode(result.getBytes(2));
                if (!document.metadata().sessionId().equals(sessionId) || document.revision() != revision) {
                    throw new IllegalStateException("SQLite Session row and document revisions disagree");
                }
                return Optional.of(document);
            }
        } catch (SQLException exception) {
            throw storage("cannot load SQLite Session", exception);
        }
    }

    @Override
    public synchronized List<SessionDocument.Metadata> list() {
        requireOpen();
        var result = new ArrayList<SessionDocument.Metadata>();
        try (Statement statement = connection.createStatement();
             ResultSet rows = statement.executeQuery("SELECT document FROM ji_sessions ORDER BY created_at DESC")) {
            while (rows.next()) result.add(codec.decode(rows.getBytes(1)).metadata());
            return List.copyOf(result);
        } catch (SQLException exception) {
            throw storage("cannot list SQLite Sessions", exception);
        }
    }

    @Override
    public synchronized SessionDocument update(String sessionId, long expectedRevision,
                                               UnaryOperator<SessionDocument> transition) {
        SessionDocument current = require(sessionId, expectedRevision);
        SessionDocument next = transition.apply(current);
        requireSuccessor(current, next);
        try (PreparedStatement statement = connection.prepareStatement(
                "UPDATE ji_sessions SET revision = ?, document = ? WHERE session_id = ? AND revision = ?")) {
            statement.setLong(1, next.revision());
            statement.setBytes(2, codec.encode(next));
            statement.setString(3, sessionId);
            statement.setLong(4, expectedRevision);
            if (statement.executeUpdate() != 1) throw revisionConflict(sessionId, expectedRevision);
            return next;
        } catch (SQLException exception) {
            throw storage("cannot update SQLite Session", exception);
        }
    }

    @Override
    public synchronized SessionDocument fork(String sourceSessionId, String newSessionId, String lane,
                                             Optional<String> targetEntryId, SessionDocument.ForkPosition position,
                                             Instant createdAt, long expectedSourceRevision) {
        SessionDocument source = require(sourceSessionId, expectedSourceRevision);
        SessionDocument fork = source.fork(newSessionId, lane, targetEntryId, position, createdAt);
        return inTransaction(() -> {
            try (PreparedStatement sourceCheck = connection.prepareStatement(
                    "SELECT revision FROM ji_sessions WHERE session_id = ?")) {
                sourceCheck.setString(1, sourceSessionId);
                try (ResultSet result = sourceCheck.executeQuery()) {
                    if (!result.next() || result.getLong(1) != expectedSourceRevision) {
                        throw revisionConflict(sourceSessionId, expectedSourceRevision);
                    }
                }
            }
            try (PreparedStatement statement = connection.prepareStatement(
                    "INSERT INTO ji_sessions(session_id, revision, created_at, document) VALUES (?, ?, ?, ?)")) {
                statement.setString(1, newSessionId);
                statement.setLong(2, fork.revision());
                statement.setString(3, createdAt.toString());
                statement.setBytes(4, codec.encode(fork));
                statement.executeUpdate();
                return fork;
            }
        });
    }

    @Override
    public synchronized void delete(String sessionId, long expectedRevision) {
        requireOpen();
        Optional<SessionDocument> current = load(sessionId);
        if (current.isEmpty()) return;
        requireRevision(current.orElseThrow(), expectedRevision);
        try (PreparedStatement statement = connection.prepareStatement(
                "DELETE FROM ji_sessions WHERE session_id = ? AND revision = ?")) {
            statement.setString(1, sessionId);
            statement.setLong(2, expectedRevision);
            if (statement.executeUpdate() != 1) throw revisionConflict(sessionId, expectedRevision);
        } catch (SQLException exception) {
            throw storage("cannot delete SQLite Session", exception);
        }
    }

    @Override
    public synchronized void close() {
        if (closed) return;
        closed = true;
        try {
            connection.close();
        } catch (SQLException exception) {
            throw storage("cannot close SQLite Session repository", exception);
        }
    }

    private SessionDocument require(String sessionId, long expectedRevision) {
        SessionDocument current = load(sessionId)
                .orElseThrow(() -> new IllegalStateException("session not found: " + sessionId));
        requireRevision(current, expectedRevision);
        return current;
    }

    private <T> T inTransaction(SqlOperation<T> operation) {
        requireOpen();
        try {
            boolean priorAutoCommit = connection.getAutoCommit();
            connection.setAutoCommit(false);
            try {
                T value = operation.run();
                connection.commit();
                return value;
            } catch (RuntimeException | SQLException exception) {
                connection.rollback();
                if (exception instanceof RuntimeException runtime) throw runtime;
                if (isConstraint((SQLException) exception)) throw new IllegalStateException("session already exists", exception);
                throw storage("SQLite Session transaction failed", (SQLException) exception);
            } finally {
                connection.setAutoCommit(priorAutoCommit);
            }
        } catch (SQLException exception) {
            throw storage("SQLite Session transaction boundary failed", exception);
        }
    }

    private void requireOpen() {
        if (closed) throw new IllegalStateException("SQLite Session repository is closed");
    }

    private static void requireRevision(SessionDocument current, long expectedRevision) {
        if (current.revision() != expectedRevision) throw revisionConflict(current.metadata().sessionId(), expectedRevision);
    }

    private static void requireSuccessor(SessionDocument current, SessionDocument next) {
        if (next == null || !next.metadata().sessionId().equals(current.metadata().sessionId())
                || next.revision() != Math.incrementExact(current.revision())) {
            throw new IllegalStateException("Session transition must preserve identity and advance revision once");
        }
    }

    private static IllegalStateException revisionConflict(String sessionId, long expectedRevision) {
        return new IllegalStateException("session revision conflict for " + sessionId + ": expected " + expectedRevision);
    }

    private static boolean isConstraint(SQLException exception) {
        return exception.getErrorCode() == 19 || exception.getMessage() != null
                && exception.getMessage().toLowerCase(java.util.Locale.ROOT).contains("constraint");
    }

    private static IllegalStateException storage(String message, SQLException cause) {
        return new IllegalStateException(message, cause);
    }

    @FunctionalInterface
    private interface SqlOperation<T> {
        T run() throws SQLException;
    }
}
